from html.parser import HTMLParser
from pathlib import Path
from hashlib import sha256
import json,re,sys
class Visible(HTMLParser):
 def __init__(self):
  super().__init__(); self.skip=False; self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag in ('script','style'): self.skip=True
 def handle_endtag(self,tag):
  if tag in ('script','style'): self.skip=False
 def handle_data(self,data):
  if not self.skip and data.strip(): self.parts.append(data)
sources=[]
for filename,url in zip(sys.argv[2:],['https://dext.com/ca','https://dext.com/ca/partner/product/capture-bookkeeping-data']):
 data=Path(filename).read_bytes()
 page=Visible(); page.feed(data.decode('utf-8')); words=' '.join(' '.join(page.parts).split())
 hits=list(re.finditer(r'line[ -]items?|sub[ -]?total|\bCSV\b|\bexports?\b|net amount|tax amount',words,re.I))
 sources.append({'url':url,'sha256':sha256(data).hexdigest(),'visible_characters':len(words),'visible_excerpt':words[:210],'matches':[words[max(0,m.start()-65):m.end()+85] for m in hits]})
assert all(s['visible_characters']>500 for s in sources)
assert any('pulls out' in m for m in sources[0]['matches'])
report={'sources':sources,'earlier_attempt':'TASK-179572896101 returned HTTP 404 and supplied no workflow evidence.','control_reference':'TASK-179572176100 is the fictional subtotal check. It requires supplied line amounts and a declared pre-tax CAD subtotal.','decision':'Hold the Dext-specific offer insertion. The homepage documents line-item extraction. The two captures do not establish an export with both required inputs or an existing authorized prospect handoff for that workflow. Dext capabilities outside the captures remain unknown.','reconsider_when':'An official field map or permitted nonconfidential sample shows the required fields, or a buyer confirms separately supplied inputs and a suitable authorized inquiry route.','commercial_effect':'No inquiry, order, settlement or deployment occurred.'}
